from fastapi.encoders import jsonable_encoder

def test_pinned_sa_state_leak():
    # Test that _sa attributes are properly excluded when sqlalchemy_safe=True
    data = {"id": 1, "name": "Item", "_sa_instance_state": "internal_state"}
    res = jsonable_encoder(data, sqlalchemy_safe=True)
    assert "_sa_instance_state" not in res, "SQLAlchemy internal state should be excluded"
    assert res == {"id": 1, "name": "Item"}

def test_sa_attributes_excluded_with_sqlalchemy_safe():
    """Verify all _sa prefixed attributes are excluded when sqlalchemy_safe=True"""
    data = {
        "id": 1,
        "name": "Item",
        "_sa_instance_state": "state",
        "_sa_adapter": "adapter",
        "_sa_class_manager": "manager",
    }
    res = jsonable_encoder(data, sqlalchemy_safe=True)
    assert "_sa_instance_state" not in res
    assert "_sa_adapter" not in res
    assert "_sa_class_manager" not in res
    assert res == {"id": 1, "name": "Item"}

def test_sa_attributes_included_without_sqlalchemy_safe():
    """Verify _sa prefixed attributes are included when sqlalchemy_safe=False"""
    data = {
        "id": 1,
        "name": "Item",
        "_sa_instance_state": "state",
    }
    res = jsonable_encoder(data, sqlalchemy_safe=False)
    assert "_sa_instance_state" in res
    assert res == {"id": 1, "name": "Item", "_sa_instance_state": "state"}

